import {
  MapContainer,
  TileLayer,
  Polyline,
  Marker,
  useMap
} from "react-leaflet";
import { useEffect, useState } from "react";
import axios from "axios";
import L from "leaflet";

// 🔥 Fix marker icons
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon-2x.png",
  iconUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon.png",
  shadowUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-shadow.png",
});

// 🚀 Component to auto-fit bounds
function FitBounds({ path }) {
  const map = useMap();

  useEffect(() => {
    if (path.length > 1) {
      map.fitBounds(path, { padding: [50, 50] });
    }
  }, [path, map]);

  return null;
}

// 🚀 Component to auto-follow drone
function FollowDrone({ latest }) {
  const map = useMap();

  useEffect(() => {
    if (latest && latest.location) {
      const lat = latest.location.coordinates[1];
      const lon = latest.location.coordinates[0];

      map.flyTo([lat, lon], 18, {
        duration: 1.5
      });
    }
  }, [latest, map]);

  return null;
}

function App() {
  const [path, setPath] = useState([]);
  const [latest, setLatest] = useState(null);

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 3000);
    return () => clearInterval(interval);
  }, []);

  const fetchData = async () => {
    try {
      const res = await axios.get("http://localhost:3000/path");
      const latestRes = await axios.get("http://localhost:3000/latest");

      const coords = res.data.map(d => [
        d.location.coordinates[1],
        d.location.coordinates[0],
      ]);

      setPath(coords);
      setLatest(latestRes.data);

    } catch (err) {
      console.error("Error fetching data:", err);
    }
  };

  return (
    <div style={{ height: "100vh" }}>
      <h2 style={{ padding: "10px" }}>🚁 Drone Live Map</h2>

      {latest && (
        <div style={{ padding: "10px" }}>
          <p>Altitude: {latest.alt}</p>
          <p>Voltage: {latest.voltage}</p>
          <p>Satellites: {latest.sats}</p>
          <p>GPS: {latest.gps_fix}</p>
        </div>
      )}

      <MapContainer
        center={[12.9716, 77.5946]}
        zoom={18}
        style={{ height: "80vh", width: "100%" }}
      >
        <TileLayer
          attribution="&copy; OpenStreetMap"
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />

        {/* 🟢 Path */}
        <Polyline positions={path} color="blue" />

        {/* 📍 Marker */}
        {latest && latest.location && (
          <Marker
            position={[
              latest.location.coordinates[1],
              latest.location.coordinates[0],
            ]}
          />
        )}

        {/* 🔥 Auto Zoom */}
        <FitBounds path={path} />

        {/* 🚀 Auto Follow */}
        <FollowDrone latest={latest} />
      </MapContainer>
    </div>
  );
}

export default App;
